'use strict';
(()=>{
 const article=document.createElement('article');article.className='panel';article.innerHTML='<div class="panel-head"><div><h2>家庭支出构成</h2><p>所选期间内，各成员已录月总额的占比。</p></div></div><div class="income-composition"></div>';$('expenseReportPanel').after(article);const box=article.lastElementChild;
 function render(){if(!D.live||!current)return;box.replaceChildren();const e=current.familyExpense,profiles=(D.memberProfiles||[]).filter(p=>p.active),groups=new Map();for(const b of e.byMember){const p=profiles.find(p=>p.key===b.name),key=p?p.key:b.name==='共同'?'共同':'历史其他支出';groups.set(key,(groups.get(key)||0)+b.cents);}if(!groups.size){box.textContent='所选期间尚无可完整计入的月度支出；未填月份不会补0。';return;}if([...groups.values()].some(v=>v<0)){box.textContent='包含退款冲减后的负支出，无法用饼图表达占比，请查看支出曲线和明细。';return;}const total=[...groups.values()].reduce((a,b)=>a+b,0);if(!total){box.textContent='所选期间已录净支出合计为0。';return;}
 const parts=[...groups].filter(([,cents])=>cents>0).map(([key,cents])=>({key,cents,name:profiles.find(p=>p.key===key)?.name||(key==='共同'?'未拆分家庭支出':key),share:cents/total})),color=key=>{const p=profiles.find(p=>p.key===key);return p?FamilyChartAxis.memberColor(p,profiles.indexOf(p)):'#8d929f';},tip=document.createElement('p');tip.className='composition-tip';tip.setAttribute('role','status');tip.textContent='图上直接标注成员、金额和占比。';const describe=p=>p.name+'：'+money(p.cents)+' · '+FamilyChartLabels.percent(p.share),svg=FamilyChartLabels.donut(parts,{width:Math.max(280,Math.min(box.clientWidth||320,440)),title:'家庭支出构成',total,color,onSelect:key=>tip.textContent=describe(parts.find(p=>p.key===key)),onFocus:text=>tip.textContent=text});
 const legend=document.createElement('div');legend.className='composition-legend';for(const p of parts){const b=document.createElement('button');b.className='composition-member';b.type='button';const dot=document.createElement('i');dot.style.background=color(p.key);const label=document.createElement('span');label.textContent=p.name;const value=document.createElement('strong');value.textContent=money(p.cents)+' · '+FamilyChartLabels.percent(p.share);b.append(dot,label,value);b.onclick=()=>tip.textContent=describe(p);legend.append(b);}box.append(svg,legend,tip);const note=document.createElement('p');note.className='muted full';note.textContent=e.unresolved.length?'有月总额被日期边界截断，图表仅含可完整定位的月份。':'只统计已录支出；没有分人数据的月份单独显示，不自动摊给成员。';box.append(note);
 }
 window.FamilyExpenseComposition={render};const old=window.FamilyInline.draw;window.FamilyInline.draw=()=>{old();render();};const baseRender=window.render;window.render=function(){baseRender();render();};document.addEventListener('family-ledger-ready',render);window.addEventListener('hashchange',()=>requestAnimationFrame(render));window.addEventListener('resize',()=>requestAnimationFrame(render));if(D.live)render();
})();
